"""K9 — good-and-separated (Gen 1:4). Why divide light from darkness, and is darkness a creature,
an evil, or the wicked? Built 2026-09-05 (Phase 2, crux 7 of 9). See PHASES.md for the contract.

Gen 1:4 is the verse K8 (`first-light`) built most heavily, and every Latin slice below was checked
with scripts/overlap.py by OFFSET before it was written; all twenty came back FREE. Two rabbinic
passages could not be handled that way and are logged in notes/cross-crux.md: K8's `br-3-6` swallowed
the whole Sefaria segment, including the va-yavdel material that is this crux's core, and K8's
`rashi-1-4` is one dibbur carrying both cruxes' answers. BR 3:6's second half is rebuilt here as
`br-3-6b` on its own lemma — the frozen rule forbids merging distinct arguments to save a card, and
the havdala derivation is a different argument from the stored light — so Phase 4 must trim `br-3-6`
to its first half. Rashi is left alone: his dibbur really is one continuous argument.
"""
import json, pathlib
from bench import ROOT, RAW, latin, sef, hcut, DRAFT, APPROVED, thread

CRUX_ID = "good-and-separated"
SHORT = "va-yavdel / divisit"
E = lambda i, f, t, ty, ev: thread(CRUX_ID, i, f, t, ty, ev)

WITNESSES = []
def add(**kw): WITNESSES.append(kw)

def _flat(x): return x if isinstance(x, str) else " ".join(_flat(i) for i in x)
def _raw(f, lang, idx):
    d = json.load(open(RAW / f))
    v = [x for x in d["versions"] if x["language"] == lang][0]
    return _flat(v["text"][idx]), v["versionTitle"]

